public class ServerPlayer extends net.minecraft.world.entity.player.Player {public ServerLevel world;public boolean removed,alive=true,spectator;public Vec3 eye=new Vec3(0,0,0),look=new Vec3(1,0,0);public final List<Component> chat=new ArrayList<>();public final CompoundTag data=new CompoundTag();public ServerPlayer(ServerLevel l){world=l;}public boolean isRemoved(){return removed;}public boolean isAlive(){return alive;}public boolean isSpectator(){return spectator;}public ServerLevel serverLevel(){return world;}public Vec3 getEyePosition(){return eye;}public Vec3 getLookAngle(){return look;}public CompoundTag getPersistentData(){return data;}public void sendSystemMessage(Component c){chat.add(c);}}
